using chatai.Core.Config;
using Microsoft.AspNetCore.Http;
using Microsoft.IdentityModel.Tokens;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Security.Cryptography;
using System.Text;
using static chatai.Core.Enumeration.SystemEnum;

namespace chatai_backend.Helpers
{
    public class JWTHelper
    {
        private static IServiceProvider _serviceProvider;
        private static string _issuer = string.Empty;
        private static string _jwtSecret = string.Empty;

        public static void Configure(IServiceProvider serviceProvider)
        {
            _serviceProvider = serviceProvider;
            _issuer = appSettingConfig.BaseUrl;
            _jwtSecret = appSettingConfig.JwtSecret;
        }

        private static ILogger<JWTHelper> logger => _serviceProvider.GetRequiredService<ILogger<JWTHelper>>();

        private static AppSettingConfig appSettingConfig => _serviceProvider.GetRequiredService<AppSettingConfig>();

        /// <summary>
        /// 取得User Signing Key
        /// </summary>
        /// <param name="regNo"></param>
        /// <returns></returns>
        private static SymmetricSecurityKey GetUserKey(string regNo)
        {
            var keySource = Encoding.UTF8.GetBytes(_jwtSecret);
            using var hmac = new HMACSHA512(keySource);
            var userKey = hmac.ComputeHash(Encoding.UTF8.GetBytes(regNo));
            return new SymmetricSecurityKey(userKey);
        }

        /// <summary>
        /// 產生Token
        /// </summary>
        /// <param name="accountName"></param>
        /// <param name="chineseName"></param>
        /// <param name="accountTypeCode"></param>
        /// <param name="expireMinutes"></param>
        /// <returns></returns>
        public static (string token, DateTime loginDate, DateTime expDate) GenerateToken(string accountName, string? chineseName, string accountTypeCode, int expireMinutes = 480)
        {
            var utcNow = DateTimeOffset.UtcNow;
            var localNow = utcNow.ToOffset(TimeSpan.FromHours(8)).DateTime;
            var localExp = localNow.AddMinutes(expireMinutes);

            var claims = new List<Claim>
            {
                new Claim(JwtRegisteredClaimNames.UniqueName, accountName),
                new Claim(JwtRegisteredClaimNames.Sub, accountName),
                new Claim(CustomClaimNames.AccountName, accountName),
                new Claim(CustomClaimNames.ChineseName, chineseName),
                new Claim(CustomClaimNames.AccountTypeCode, accountTypeCode),
                new Claim(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString()),
                new Claim(JwtRegisteredClaimNames.Iat, utcNow.ToUnixTimeSeconds().ToString(), ClaimValueTypes.Integer64),
                new Claim(JwtRegisteredClaimNames.Iss, _issuer),
            };

            var signingKey = GetUserKey(accountName);

            var jwt = new JwtSecurityToken(
                issuer: _issuer,
                claims: claims,
                notBefore: localNow,
                expires: localExp,
                signingCredentials: new SigningCredentials(signingKey, SecurityAlgorithms.HmacSha512Signature)
            );

            var token = new JwtSecurityTokenHandler().WriteToken(jwt);
            return (token, localNow, localExp);
        }

        /// <summary>
        /// 驗證Token
        /// </summary>
        /// <param name="authToken"></param>
        /// <param name="principal"></param>
        /// <returns></returns>
        public static bool ValidateToken(string authToken, out ClaimsPrincipal? principal)
        {
            principal = null;

            try
            {
                var tokenHandler = new JwtSecurityTokenHandler();
                var token = authToken?.Split(' ').LastOrDefault();

                if (string.IsNullOrWhiteSpace(token))
                {
                    logger.LogWarning("Token is null or empty.");
                    return false;
                }

                var jwt = tokenHandler.ReadJwtToken(token);
                var accountName = jwt.Claims.FirstOrDefault(x => x.Type == JwtRegisteredClaimNames.Sub)?.Value;

                if (string.IsNullOrWhiteSpace(accountName))
                {
                    logger.LogWarning("Missing Subject (accountName) in token.");
                    return false;
                }

                principal = tokenHandler.ValidateToken(token, new TokenValidationParameters
                {
                    NameClaimType = ClaimTypes.NameIdentifier,
                    ValidateAudience = false,
                    ValidateLifetime = false, // 你也可以改成 true，看你要不要加時間驗證
                    ClockSkew = TimeSpan.Zero,
                    IssuerSigningKey = GetUserKey(accountName),
                    ValidateIssuer = true,
                    ValidIssuer = _issuer,
                }, out SecurityToken validatedToken);

                var now = DateTime.UtcNow.AddSeconds(60);
                if (validatedToken is JwtSecurityToken jwtToken)
                {
                    if (jwtToken.ValidFrom > now || jwtToken.ValidTo < now)
                    {
                        logger.LogInformation($"Token expired. ValidFrom: {jwtToken.ValidFrom:yyyy/MM/dd HH:mm:ss}, Now: {now:yyyy/MM/dd HH:mm:ss}, ValidTo: {jwtToken.ValidTo:yyyy/MM/dd HH:mm:ss}");
                        return false;
                    }
                }

                return true;
            }
            catch (Exception ex)
            {
                logger.LogError(ex, "Token validation failed.");
                return false;
            }
        }

        /// <summary>
        /// 從 X-Access-Token header 解析並驗證 JWT，取回 AccountName claim。
        /// 注意：ValidateJWTFilter 只驗證 token 有效性，不會把 claims 寫進 HttpContext.User
        /// （HttpContext.User 是給 SAML SSO cookie 登入流程用的），所以需要 JWT 身份的 API
        /// 要自己重新解析 header，不能透過 AuthorizeManagement.CurrentUser 取得。
        /// </summary>
        public static string? GetAccountNameFromRequest(HttpRequest request)
        {
            if (!request.Headers.TryGetValue("X-Access-Token", out var authToken))
                return null;

            if (!ValidateToken(authToken.ToString(), out var principal) || principal == null)
                return null;

            return principal.FindFirst(CustomClaimNames.AccountName)?.Value;
        }

        /// <summary>
        /// 從 X-Access-Token header 解析並驗證 JWT，取回 AccountTypeCode claim（"f"=教師／"u"=學生／
        /// "s"=職員...，見 ntu.Sso.Enumeration.AccountEnum.AccountTypeCodeEnum）。
        /// 目前給 flowId=8（未來教室設備支援助理）用來輔助判斷「老師／學生」身分，減少每次都要
        /// 使用者自己輸入身分的摩擦；沒有 token 或解析失敗時回傳 null。
        /// </summary>
        public static string? GetAccountTypeCodeFromRequest(HttpRequest request)
        {
            if (!request.Headers.TryGetValue("X-Access-Token", out var authToken))
                return null;

            if (!ValidateToken(authToken.ToString(), out var principal) || principal == null)
                return null;

            return principal.FindFirst(CustomClaimNames.AccountTypeCode)?.Value;
        }
    }
}

