import { STORAGE_KEYS } from '@/storage/keys'

const DEFAULT_MODEL = 'claude'

/**
 * 從 _frontend/chatai 整頁導過來時，網址帶著 ?token=<jwt>（同源時其實不需要，是跨源部署時的保險）、
 * 選擇性帶 ?model=<gemini|openai|claude>（對應原本 ?flow=7&model=... 的模型切換能力）。
 * 讀出來寫進 localStorage 後就把這兩個參數從網址上拿掉，避免留在瀏覽紀錄或分享出去的連結裡。
 */
export function consumeIncomingParams(): void {
  const params = new URLSearchParams(window.location.search)
  const token = params.get('token')
  const model = params.get('model')
  if (!token && !model) return

  try {
    if (token) localStorage.setItem(STORAGE_KEYS.jwtToken, token)
    if (model) localStorage.setItem(STORAGE_KEYS.model, model)
  } catch {
    // localStorage unavailable（配額用完、隱私模式）— readAuthToken()/readModelPreference() 會拿不到值
  }

  params.delete('token')
  params.delete('model')
  const query = params.toString()
  const url = `${window.location.pathname}${query ? `?${query}` : ''}${window.location.hash}`
  window.history.replaceState(null, '', url)
}

export function readAuthToken(): string | null {
  try {
    return localStorage.getItem(STORAGE_KEYS.jwtToken)
  } catch {
    return null
  }
}

/** flow=7 底層要用哪個 AI 供應商呼叫 AdvisingChatService；沒特別指定時預設 claude（不是後端原本的 gemini）。 */
export function readModelPreference(): string {
  try {
    return localStorage.getItem(STORAGE_KEYS.model) || DEFAULT_MODEL
  } catch {
    return DEFAULT_MODEL
  }
}

/** 沒有登入態時導回主聊天站的登入頁；VITE_LOGIN_URL 未設定時什麼都不做（避免開發環境誤跳轉）。 */
export function redirectToLogin(): void {
  const loginUrl = import.meta.env.VITE_LOGIN_URL as string | undefined
  if (loginUrl) window.location.href = loginUrl
}

import { readAuthToken } from './auth'
import { getApiUrl } from './advisingApi'
import type {
  Answer,
  ConversationTurn,
  Exploration,
  ExplorationStatus,
  FastAssessment,
  SelfAwarenessCard,
  SummarySection,
  TopicKey
} from '@/types'

export class ExplorationApiError extends Error {
  status?: number

  constructor(message: string, status?: number) {
    super(message)
    this.status = status
  }
}

/** 對應後端 ExplorationController 的 ExplorationResponse（camelCase JSON，見 chatai_backend 的 JsonOptions 預設）。 */
interface ExplorationDto {
  id: string
  topic: TopicKey
  topicCustomLabel?: string | null
  status: ExplorationStatus
  history?: ConversationTurn[] | null
  answers?: Answer[] | null
  summary?: SummarySection[] | null
  card?: SelfAwarenessCard | null
  fast?: FastAssessment | null
  createdAt: string
  updatedAt: string
}

function toExploration(dto: ExplorationDto): Exploration {
  return {
    id: dto.id,
    topic: dto.topic,
    topicCustomLabel: dto.topicCustomLabel ?? undefined,
    answers: dto.answers ?? [],
    summary: dto.summary ?? undefined,
    card: dto.card ?? undefined,
    status: dto.status,
    createdAt: dto.createdAt,
    updatedAt: dto.updatedAt,
    history: dto.history ?? [],
    fast: dto.fast ?? undefined
  }
}

async function authorizedFetch(path: string, init: RequestInit = {}): Promise<Response> {
  const token = readAuthToken()
  if (!token) throw new ExplorationApiError('缺少登入憑證')

  const res = await fetch(getApiUrl(path), {
    ...init,
    headers: {
      'Content-Type': 'application/json',
      'X-Access-Token': `Bearer ${token}`,
      ...(init.headers ?? {})
    }
  })

  if (!res.ok) {
    const errorText = await res.text().catch(() => '')
    throw new ExplorationApiError(errorText || `探索紀錄 API 請求失敗 (${res.status})`, res.status)
  }

  return res
}

export async function listExplorations(): Promise<Exploration[]> {
  const res = await authorizedFetch('/api/explorations')
  const dtos = (await res.json()) as ExplorationDto[]
  return dtos.map(toExploration).sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime())
}

export async function findInProgress(): Promise<Exploration | null> {
  const all = await listExplorations()
  return all.find(r => r.status === 'in-progress') ?? null
}

/** 找不到，或這筆紀錄不屬於目前登入的使用者（後端一律回 404，不區分兩者）時回傳 null。 */
export async function getExploration(id: string): Promise<Exploration | null> {
  try {
    const res = await authorizedFetch(`/api/explorations/${id}`)
    return toExploration((await res.json()) as ExplorationDto)
  } catch (err) {
    if (err instanceof ExplorationApiError && err.status === 404) return null
    throw err
  }
}

export async function createExploration(input: { topic: TopicKey; topicCustomLabel?: string }): Promise<Exploration> {
  const res = await authorizedFetch('/api/explorations', {
    method: 'POST',
    body: JSON.stringify({ topic: input.topic, topicCustomLabel: input.topicCustomLabel })
  })
  return toExploration((await res.json()) as ExplorationDto)
}

/**
 * 更新 answers/summary/card/fast/status 這幾個前端解析出來的衍生欄位；history（AI 對話的權威狀態）
 * 不在這裡動，由 RunController.RunAdvisingExploreFlow 在每輪對話結束後直接存回去。
 */
export async function updateExplorationDerived(
  id: string,
  patch: {
    answers?: Answer[]
    summary?: SummarySection[]
    card?: SelfAwarenessCard
    fast?: FastAssessment
    status?: ExplorationStatus
  }
): Promise<void> {
  await authorizedFetch(`/api/explorations/${id}`, {
    method: 'PATCH',
    body: JSON.stringify(patch)
  })
}

/** 「修改上一題答案」用：把後端的 history 截回到 historyLength 這個長度。 */
export async function truncateExploration(id: string, historyLength: number): Promise<void> {
  await authorizedFetch(`/api/explorations/${id}/truncate`, {
    method: 'POST',
    body: JSON.stringify({ historyLength })
  })
}

export async function deleteExploration(id: string): Promise<void> {
  await authorizedFetch(`/api/explorations/${id}`, { method: 'DELETE' })
}

import { inject, onUnmounted, provide, ref, watch, type InjectionKey, type Ref } from 'vue'
import type { Answer, Exploration, SelfAwarenessCard, SummarySection } from '@/types'
import { getExploration, truncateExploration, updateExplorationDerived } from '@/services/explorationApi'
import { useAutosave } from './useAutosave'

interface ExplorationContextValue {
  exploration: Ref<Exploration | null>
  loading: Ref<boolean>
  setAnswer: (questionIndex: number, text: string) => void
  truncateAfter: (questionIndex: number) => Promise<void>
  finish: (summary: SummarySection[], card: SelfAwarenessCard) => void
}

const ExplorationKey: InjectionKey<ExplorationContextValue> = Symbol('Exploration')

/**
 * 依 id（可為 route param 的 reactive ref）提供一份探索紀錄的讀寫狀態，answers/summary/card/fast/status
 * 這幾個衍生欄位會自動 debounce PATCH 回後端。history（AI 對話的權威狀態）不在這裡寫，
 * 由 RunController.RunAdvisingExploreFlow 在每輪對話結束後直接存回去（見 useAdvisingConversation.ts）。
 */
export function provideExploration(id: Ref<string>): ExplorationContextValue {
  const exploration = ref<Exploration | null>(null) as Ref<Exploration | null>
  const loading = ref(true)

  async function load(explorationId: string) {
    loading.value = true
    try {
      exploration.value = await getExploration(explorationId)
    } catch (err) {
      console.error('[useExploration] load failed', err)
      exploration.value = null
    } finally {
      loading.value = false
    }
  }

  void load(id.value)

  const { flush } = useAutosave(
    exploration,
    e => {
      if (!e) return
      updateExplorationDerived(e.id, {
        answers: e.answers,
        summary: e.summary,
        card: e.card,
        fast: e.fast,
        status: e.status
      }).catch(err => {
        console.error('[useExploration] autosave failed', err)
      })
    },
    300
  )

  // id 改變時（切換到不同探索，或同一路由帶不同 ?q）：先把舊紀錄的待寫入內容存檔，再載入新紀錄
  watch(id, (newId, oldId) => {
    if (oldId !== undefined) flush()
    void load(newId)
  })

  onUnmounted(flush)

  const setAnswer = (questionIndex: number, text: string) => {
    const prev = exploration.value
    if (!prev) return
    const now = new Date().toISOString()
    const answers: Answer[] = [...prev.answers]
    const idx = answers.findIndex(a => a.questionIndex === questionIndex)
    if (idx >= 0) answers[idx] = { ...answers[idx], text, updatedAt: now }
    else answers.push({ questionIndex, text, updatedAt: now })
    exploration.value = { ...prev, answers, updatedAt: now }
  }

  /**
   * 「修改上一題答案」：answers 在本機截掉，history 交給後端截（POST .../truncate）。
   * 兩邊都要截，否則下次送出時後端會從沒截過的 history 判斷題號，跟畫面顯示的題號對不上。
   */
  const truncateAfter = async (questionIndex: number) => {
    const prev = exploration.value
    if (!prev) return
    const keptAnswers = questionIndex < 0 ? [] : prev.answers.filter(a => a.questionIndex <= questionIndex)
    // 真實對話模式下，把 history 也截回這題結束當下的長度，才不會讓後端收到使用者已經捨棄的未來回合
    // （見 Answer.historyLength 的說明）；找不到記錄長度（例如解析失敗保底資料）就整包保留不動。
    const keptHistoryLength = questionIndex < 0 ? 0 : keptAnswers.at(-1)?.historyLength

    if (keptHistoryLength !== undefined) {
      await truncateExploration(prev.id, keptHistoryLength)
    }

    exploration.value = {
      ...prev,
      answers: keptAnswers,
      history: keptHistoryLength !== undefined ? prev.history?.slice(0, keptHistoryLength) : prev.history,
      summary: undefined,
      card: undefined,
      status: 'in-progress',
      updatedAt: new Date().toISOString()
    }
  }

  const finish = (summary: SummarySection[], card: SelfAwarenessCard) => {
    const prev = exploration.value
    if (!prev) return
    exploration.value = { ...prev, summary, card, status: 'completed', updatedAt: new Date().toISOString() }
  }

  const value: ExplorationContextValue = { exploration, loading, setAnswer, truncateAfter, finish }
  provide(ExplorationKey, value)
  return value
}

export function useExploration(): ExplorationContextValue {
  const ctx = inject(ExplorationKey)
  if (!ctx) throw new Error('useExploration must be used within a component tree that called provideExploration()')
  return ctx
}

import { createApp } from 'vue'
import App from './App.vue'
import { router } from './router'
import { i18n } from './i18n'
import { consumeIncomingParams, readAuthToken, redirectToLogin } from './services/auth'
import './styles/tokens.css'
import './styles/global.css'

consumeIncomingParams()

if (!readAuthToken()) {
  redirectToLogin()
} else {
  createApp(App).use(router).use(i18n).mount('#app')
}

