import { createApp, inject } from "vue";
import { createRouter, createWebHistory } from "vue-router";
import { VueQueryPlugin } from "@tanstack/vue-query";
import { LocalStorageKey } from "@/lib/constant";
import App from "@/App.vue";
import "@/assets/index.css";
import { jwtDecode } from "jwt-decode";
import { JwtToken } from "@/lib/type";

const app = createApp(App);
app.use(VueQueryPlugin);

try {
  const jwtToken = localStorage.getItem(LocalStorageKey.JWT_TOKEN);
  // Check if the token exists
  if (!jwtToken) throw new Error("No JWT token found in local storage");
  const user = jwtDecode<JwtToken>(jwtToken);
  // Check if the token is expired (allowing a grace period of 8 hours)
  if (user?.iat && Math.floor(Date.now() / 1000) - user.iat > 8 * 60 * 60)
    throw new Error("Token expired");
  app.provide("user", user);
} catch (error) {
  localStorage.removeItem(LocalStorageKey.JWT_TOKEN);
  app.provide("user", null);
}

const routes = [
  { path: "/", component: () => import("@/views/HomeView.vue") },
  { path: "/help", component: () => import("@/views/help/HelpPage.vue") },
  { path: "/docs", component: () => import("@/views/docs/DocsPage.vue") },
  { path: "/login", component: () => import("@/views/login/LoginPage.vue") },
  { path: "/rating", component: () => import("@/views/rating/RatingPage.vue") },
];

const router = createRouter({
  history: createWebHistory(),
  routes,
});

router.beforeEach((to) => {
  const isAuthenticated = inject("user") !== null;
  if (to.path === "/login" && isAuthenticated) return "/";
  if (to.path !== "/login" && !isAuthenticated) return "/login";
  // flow=7（學習規劃探索助手）改用獨立部署的沉浸式體驗，整頁導出去，
  // 不在這顆共用 SPA 裡渲染，避免動到 MainPage/InputBlock/ChatProvider 影響其他 flow。
  if (to.path === "/" && isAuthenticated && to.query.flow === "7") {
    const exploreUrl = import.meta.env.VITE_EXPLORE_URL;
    if (exploreUrl) {
      const token = localStorage.getItem(LocalStorageKey.JWT_TOKEN) ?? "";
      const params = new URLSearchParams({ token });
      // 例如 ?flow=7&model=claude 一併轉發過去，讓 app-vue 那邊沿用同一套模型切換能力
      if (to.query.model) params.set("model", String(to.query.model));
      window.location.href = `${exploreUrl.replace(/\/$/, "")}/?${params.toString()}`;
      return false;
    }
  }
  if (to.path === "/" && isAuthenticated && !to.query.flow) {
    return { path: "/", query: { ...to.query, flow: "6" } };
  }
  return true;
});

app.use(router).mount("#app");

