import { type Ref } from "vue";
import { getApiUrl } from "@/lib/utils";

export interface FileUploadContext {
  jwtToken: Ref<string>;
}

const MAX_FILE_SIZE_BYTES = 50 * 1024 * 1024; // 50MB，需與後端 GeminiController 的限制一致

/**
 * 上傳文件到 flowId=6 用的個人知識庫（Gemini File Search）
 * 回傳後端的提示訊息（例如「文件上傳中，索引可能需要幾分鐘」）
 */
export async function uploadFile(
  context: FileUploadContext,
  file: File,
): Promise<string> {
  if (file.size > MAX_FILE_SIZE_BYTES) {
    throw new Error("檔案大小超過 50MB 上限");
  }

  const formData = new FormData();
  formData.append("file", file, file.name);

  const res = await fetch(getApiUrl("/api/gemini/upload"), {
    method: "POST",
    headers: {
      "X-Access-Token": `Bearer ${context.jwtToken.value}`,
    },
    body: formData,
  });

  if (!res.ok) {
    const errorText = await res.text();
    throw new Error(errorText || `上傳失敗 (${res.status})`);
  }

  const data = await res.json();
  return data.message ?? "文件上傳中，索引可能需要幾分鐘，完成後即可查詢。";
}

