import { nextTick } from "vue";
import { twMerge } from "tailwind-merge";
import { type ClassValue, clsx } from "clsx";
import { SCROLL_ID } from "@/lib/constant";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function toChatBottom(options?: ScrollToOptions) {
  const mainScroll = document.getElementById(SCROLL_ID);
  const container = mainScroll?.children[0];
  nextTick(() =>
    container?.scrollTo({ top: container.scrollHeight, ...options }),
  );
}

export function getApiUrl(path: string): string {
  const API_URL = import.meta.env.VITE_API_URL;
  const normalizedPath = path.startsWith("/") ? path : `/${path}`;
  if (!API_URL?.trim()) return normalizedPath;
  const baseUrl = API_URL.replace(/\/$/, "");
  return `${baseUrl}${normalizedPath}`;
}

