/// <summary>
/// 檢查 X-Access-Token 是否已過半效期（剩餘效期 &lt; 總效期的一半），若是則簽發一顆全新的
/// 8 小時 token 讓前端換掉舊的，達到「持續活躍就不會過期」的 sliding expiration 效果；
/// 沒有 header、驗證失敗（已過期／竄改）或還沒過半效期則回傳 null，不做任何事。
/// 已過期的 token 一律不會被這裡救回來——過期後還是要走真正的重新登入。
/// </summary>
public static string? TryRenewToken(HttpRequest request)
{
    if (!request.Headers.TryGetValue("X-Access-Token", out var authTokenHeader))
        return null;

    var authToken = authTokenHeader.ToString();
    if (!ValidateToken(authToken, out var principal) || principal == null)
        return null;

    var token = authToken.Split(' ').LastOrDefault();
    if (string.IsNullOrWhiteSpace(token))
        return null;

    var jwt = new JwtSecurityTokenHandler().ReadJwtToken(token);
    var totalLifetime = jwt.ValidTo - jwt.ValidFrom;
    var remaining = jwt.ValidTo - DateTime.UtcNow;
    if (totalLifetime <= TimeSpan.Zero || remaining > totalLifetime / 2)
        return null;

    var accountName = principal.FindFirst(CustomClaimNames.AccountName)?.Value;
    var accountTypeCode = principal.FindFirst(CustomClaimNames.AccountTypeCode)?.Value;
    if (string.IsNullOrWhiteSpace(accountName) || string.IsNullOrWhiteSpace(accountTypeCode))
        return null;

    var chineseName = principal.FindFirst(CustomClaimNames.ChineseName)?.Value;

    var (newToken, _, _) = GenerateToken(accountName, chineseName, accountTypeCode);
    return newToken;
}

