using chatai.Core;
using chatai_backend.Filter;
using chatai_backend.Helpers;
using chatai_backend.Model;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.HttpOverrides;
using NLog;
using NLog.Web;
using ntu.Common.Utility.Extension;
using Sustainsys.Saml2;
using Sustainsys.Saml2.AspNetCore2;
using Sustainsys.Saml2.Metadata;
using Sustainsys.Saml2.Saml2P;
using System.Diagnostics;
using System.Security.Cryptography.X509Certificates;
using System.Text.Json.Serialization;

var builder = WebApplication.CreateBuilder(args);
var env = builder.Environment;

var frontUrl = builder.Configuration.GetValue<string>("FrontUrl")!;
var baseUrl = builder.Configuration.GetValue<string>("BaseUrl")!;
string? baseUrlPath = builder.Configuration["BaseUrlPath"]?.ToNullString();

builder.Services.AddCoreServices();

builder.Services.AddScoped<SignatureContext>();

LogManager.Setup().SetupExtensions(ext =>
{
    ext.RegisterLayoutRenderer("trace-id", logevent => Activity.Current?.TraceId.ToString());
    ext.RegisterLayoutRenderer("spanId-id", logevent => Activity.Current?.SpanId.ToString());
});

builder.Services.AddLogging((configure) =>
{
    configure.AddNLog("nlog.config");
});

builder.Services.AddAuthentication(options =>
{
    options.DefaultScheme = CookieAuthenticationDefaults.AuthenticationScheme;
    options.DefaultChallengeScheme = Saml2Defaults.Scheme;
})
.AddCookie(options =>
{
    options.ExpireTimeSpan = TimeSpan.FromHours(8);
    //options.SlidingExpiration = true; // �ҥηưʹL��
})
.AddSaml2(options =>
{
    var env = builder.Environment;
    var certPath = Path.Combine(env.ContentRootPath, "App_Data", "sso.pfx");
    options.SPOptions.NameIdPolicy = new Saml2NameIdPolicy(true, NameIdFormat.Unspecified);
    options.SPOptions.EntityId = new EntityId(frontUrl);
    options.SPOptions.PublicOrigin = new Uri(frontUrl);

    if (!string.IsNullOrEmpty(baseUrlPath))
    {
        options.SPOptions.ModulePath = $"/{baseUrlPath}/Saml2";
    }

    options.SPOptions.ServiceCertificates.Add(new X509Certificate2(certPath, "612"));
    options.IdentityProviders.Add(new IdentityProvider(
        new EntityId("https://portal.aca.ntu.edu.tw/sso-gateway/"),
        options.SPOptions)
    {
        MetadataLocation = "https://portal.aca.ntu.edu.tw/sso-gateway/idp/metadata",
        LoadMetadata = true,
        AllowUnsolicitedAuthnResponse = true
    });
});

builder.Services.AddControllersWithViews(config =>
{
    config.Filters.Add(typeof(ValidateSignatureFilter));
    config.Filters.Add(typeof(ValidateJWTFilter));
    config.Filters.Add(typeof(ExceptionFilter));
}).AddJsonOptions(options =>
{
    options.JsonSerializerOptions.Converters.Add(new JsonStringEnumConverter());
}).AddKebabCaseRouting();

builder.Services.AddHttpClient("NoSsl", client =>
{
    client.Timeout = TimeSpan.FromSeconds(60 * 5);
}).ConfigurePrimaryHttpMessageHandler(() => new HttpClientHandler
    {
        ServerCertificateCustomValidationCallback = HttpClientHandler.DangerousAcceptAnyServerCertificateValidator
    });

var policyDomains = builder.Configuration.GetSection("PolicyDomain").Get<string[]>();
var allowSpecificOrigins = "_allowSpecificOrigins";

builder.Services.AddCors(options =>
{
    options.AddPolicy(name: allowSpecificOrigins,
        policy =>
        {
            policy.WithOrigins(policyDomains)
                  .AllowAnyHeader()
            .AllowAnyMethod();
        });
});

var app = builder.Build();
var serviceProvider = app.Services;
var configuration = app.Configuration;

DependencyInjection.Init(serviceProvider);

AuthorizeManagement.Configure(serviceProvider);
JWTHelper.Configure(serviceProvider);

// Configure the HTTP request pipeline.
if (!env.IsDevelopment())
{
    app.UseExceptionHandler("/Error");
    // The default HSTS value is 30 days. You may want to change this for production scenarios, see https://aka.ms/aspnetcore-hsts.
    app.UseHsts();
}

if (!string.IsNullOrEmpty(baseUrlPath))
    app.UsePathBase($"/{baseUrlPath}");

app.UseForwardedHeaders(new ForwardedHeadersOptions
{
    ForwardedHeaders = ForwardedHeaders.XForwardedFor | ForwardedHeaders.XForwardedProto | ForwardedHeaders.XForwardedHost
});

app.UseDefaultFiles();
app.UseStaticFiles();

app.UseCors(allowSpecificOrigins);
app.UseRouting();
app.UseAuthorization();
app.MapControllers();

app.Run();

