import { STORAGE_KEYS } from '@/storage/keys'

const DEFAULT_MODEL = 'claude'

/**
 * 從 _frontend/chatai 整頁導過來時，網址帶著 ?token=<jwt>（同源時其實不需要，是跨源部署時的保險）、
 * 選擇性帶 ?model=<gemini|openai|claude>（對應原本 ?flow=7&model=... 的模型切換能力）。
 * 讀出來寫進 localStorage 後就把這兩個參數從網址上拿掉，避免留在瀏覽紀錄或分享出去的連結裡。
 */
export function consumeIncomingParams(): void {
  const params = new URLSearchParams(window.location.search)
  const token = params.get('token')
  const model = params.get('model')
  if (!token && !model) return

  try {
    if (token) localStorage.setItem(STORAGE_KEYS.jwtToken, token)
    if (model) localStorage.setItem(STORAGE_KEYS.model, model)
  } catch {
    // localStorage unavailable（配額用完、隱私模式）— readAuthToken()/readModelPreference() 會拿不到值
  }

  params.delete('token')
  params.delete('model')
  const query = params.toString()
  const url = `${window.location.pathname}${query ? `?${query}` : ''}${window.location.hash}`
  window.history.replaceState(null, '', url)
}

export function readAuthToken(): string | null {
  try {
    return localStorage.getItem(STORAGE_KEYS.jwtToken)
  } catch {
    return null
  }
}

/** flow=7 底層要用哪個 AI 供應商呼叫 AdvisingChatService；沒特別指定時預設 claude（不是後端原本的 gemini）。 */
export function readModelPreference(): string {
  try {
    return localStorage.getItem(STORAGE_KEYS.model) || DEFAULT_MODEL
  } catch {
    return DEFAULT_MODEL
  }
}

/** 沒有登入態時導回主聊天站的登入頁；VITE_LOGIN_URL 未設定時什麼都不做（避免開發環境誤跳轉）。 */
export function redirectToLogin(): void {
  const loginUrl = import.meta.env.VITE_LOGIN_URL as string | undefined
  if (loginUrl) window.location.href = loginUrl
}

