/**
 * 後端在 token 過半效期時會用 X-Access-Token-Renewed response header 換發一顆新的（見
 * chatai_backend Program.cs 的 sliding renewal middleware）。設進傳入的 jwtToken ref 即可——
 * 它背後是 useLocalStorage()，設 .value 會自動寫回 localStorage，並透過 VueUse 的同頁同步
 * 機制傳播給同一 tab 內其他獨立建立的 useLocalStorage(JWT_TOKEN, ...) 實例。
 */
export function persistRenewedToken(res: Response, jwtToken: Ref<string>): void {
  const renewed = res.headers.get("X-Access-Token-Renewed");
  if (renewed) jwtToken.value = renewed;
}

