import { getApiUrl, persistRenewedToken } from "@/lib/utils";
import { encryptSignature } from "./useAICall";

export interface AudioTranscriptionContext {
  publicKey: string;
  fingerprint: Ref<string> | undefined;
  jwtToken: Ref<string>;
  isTranscribing: Ref<boolean>;
}

/**
 * 處理音頻轉錄
 */
export async function handleAudioTranscription(
  context: AudioTranscriptionContext,
  audioBlob: Blob,
): Promise<string> {
  try {
    context.isTranscribing.value = true;
    const timestamp = Date.now();
    const config = {
      flowId: "0",
    };

    if (audioBlob.size < 1000) {
      throw new Error("錄音太短，請錄製較長的語音");
    }

    const signature = await encryptSignature(
      context.publicKey,
      `${context.fingerprint?.value} ${timestamp} ${config.flowId}`,
    );

    const formData = new FormData();
    // Determine filename based on MIME type
    let fileName = "audio.webm";
    if (audioBlob.type.includes("wav")) fileName = "audio.wav";
    else if (audioBlob.type.includes("mp3")) fileName = "audio.mp3";
    else if (audioBlob.type.includes("mp4")) fileName = "audio.mp4";
    else if (audioBlob.type.includes("ogg")) fileName = "audio.ogg";

    formData.append("audio", audioBlob, fileName);

    // Add timeout
    const controller = new AbortController();
    const timeoutId = setTimeout(() => {
      controller.abort();
    }, 480000); // 480 second timeout (8 minutes)

    try {
      const response = await fetch(getApiUrl("/api/whisper/transcribe"), {
        method: "POST",
        headers: {
          Authorization: signature,
          "X-Access-Token": `Bearer ${context.jwtToken.value}`,
        },
        body: formData,
        signal: controller.signal,
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        let errorMessage = "";

        try {
          const errorData = await response.json();
          errorMessage = errorData.error || "";
          console.error(
            `Transcription error (${response.status}):`,
            errorMessage,
          );
        } catch (parseError) {
          console.error("Transcription error: Failed to parse error response");
          errorMessage = `HTTP error! status: ${response.status}`;
        }

        throw new Error(
          errorMessage || `HTTP error! status: ${response.status}`,
        );
      }

      const data = await response.json();

      // Handle the text field that includes "text: " prefix
      let transcribedText = data.text || "";
      if (transcribedText.startsWith("text: ")) {
        transcribedText = transcribedText.substring(6);
      }

      if (transcribedText && transcribedText.trim()) {
        return transcribedText;
      } else {
        throw new Error("無法識別語音內容，請說話清晰一些並重試");
      }
    } catch (fetchError: any) {
      if (fetchError.name === "AbortError") {
        throw new Error("請求超時，請檢查網路連接或稍後再試");
      }
      throw fetchError;
    }
  } catch (error) {
    throw error;
  } finally {
    context.isTranscribing.value = false;
  }
}

