import { computed, type Ref, type ComputedRef } from "vue";
import { useQuery } from "@tanstack/vue-query";
import { useLocalStorage } from "@vueuse/core";
import { LocalStorageKey } from "@/lib/constant";
import { getApiUrl } from "@/lib/utils";
import type { QAItem } from "@/lib/type";

export type QADesc = QAItem;

export function useQADesc(
  cid: Ref<string> | ComputedRef<string> | string | null,
) {
  const jwtToken = useLocalStorage(LocalStorageKey.JWT_TOKEN, "");

  const categoryId = computed(() =>
    typeof cid === "string" || cid === null ? cid : cid.value,
  );

  async function fetchQADesc(categoryId: string): Promise<QAItem[]> {
    const response = await fetch(getApiUrl("/api/qa/get-qa-desc"), {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Access-Token": `Bearer ${jwtToken.value}`,
      },
      body: JSON.stringify({ cid: categoryId }),
    });

    if (!response.ok) {
      throw new Error(
        `API 請求失敗: ${response.status} ${response.statusText}`,
      );
    }

    return await response.json();
  }

  const query = useQuery({
    queryKey: ["qa-desc", categoryId],
    queryFn: () => fetchQADesc(categoryId.value!),
    enabled: computed(() => !!categoryId.value),
  });

  return {
    data: query.data,
    isLoading: query.isLoading,
    error: query.error,
    refetch: query.refetch,
  };
}

