import { useQuery } from "@tanstack/vue-query";
import { useLocalStorage } from "@vueuse/core";
import { LocalStorageKey } from "@/lib/constant";
import { getApiUrl } from "@/lib/utils";

export interface QACategory {
  label: string;
  value: string;
}

export function useQACategory() {
  const jwtToken = useLocalStorage(LocalStorageKey.JWT_TOKEN, "");

  async function fetchQACategory(): Promise<QACategory[]> {
    const response = await fetch(getApiUrl("/api/qa/get-qa-category"), {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Access-Token": `Bearer ${jwtToken.value}`,
      },
    });

    if (!response.ok) {
      throw new Error(
        `API 請求失敗: ${response.status} ${response.statusText}`,
      );
    }

    const responseData: Array<{ cid: number; cname: string }> =
      await response.json();

    return responseData.map((item) => ({
      label: (item.cname || "").replace("相關", ""),
      value: String(item.cid || ""),
    }));
  }

  const query = useQuery({
    queryKey: ["qa-category"],
    queryFn: fetchQACategory,
  });

  return {
    data: query.data,
    isLoading: query.isLoading,
    error: query.error,
    refetch: query.refetch,
  };
}

