import { useQuery } from "@tanstack/vue-query";
import { useLocalStorage } from "@vueuse/core";
import { LocalStorageKey } from "@/lib/constant";
import { getApiUrl } from "@/lib/utils";
import type { QAItem } from "@/lib/type";

export type QASearchResult = QAItem;

export function useQASearch() {
  const jwtToken = useLocalStorage(LocalStorageKey.JWT_TOKEN, "");

  async function searchQA(inputValue: string): Promise<QAItem[]> {
    if (!inputValue.trim()) {
      return [];
    }

    const url = getApiUrl("/api/qa/search-qa");
    const response = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Access-Token": `Bearer ${jwtToken.value}`,
      },
      body: JSON.stringify({ input_value: inputValue }),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(
        `API 請求失敗: ${response.status} ${response.statusText}\n${errorText}`,
      );
    }

    return await response.json();
  }

  return {
    searchQA,
  };
}

export function useQASearchQuery(inputValue: string) {
  const { searchQA } = useQASearch();

  return useQuery({
    queryKey: ["qa-search", inputValue],
    queryFn: () => searchQA(inputValue),
    enabled: !!inputValue?.trim(),
  });
}

